WITH eu AS (SELECT lower(u.email) AS email, initcap(replace(replace(split_part(lower(u.email), '@', 1), '.', ' '), '_', ' ')) AS nome FROM INT_USER u WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio') AND NOT EXISTS (SELECT 1 FROM executivos e WHERE lower(e.email) = lower(u.email))) INSERT INTO executivos (nome, email, cargo) SELECT CASE WHEN EXISTS (SELECT 1 FROM executivos x WHERE x.nome = eu.nome) THEN eu.nome || ' (' || eu.email || ')' ELSE eu.nome END, eu.email, 'Equipe Zydon' FROM eu ON CONFLICT (nome) DO NOTHING RETURNING id, nome, email, cargo
